// Minimal vendored Alpine.js (subset for offline operation).
// Full source: https://github.com/alpinejs/alpine (MIT)
// This is a tiny shim implementing the subset of directives used
// by the On-Call Hero UI so the page works with no network.

(function () {
  "use strict";

  function evaluate(expr, scope) {
    try {
      const fn = new Function("with(this){return " + expr + "}");
      return fn.call(scope);
    } catch (e) {
      return undefined;
    }
  }

  function evaluateAssignment(expr, scope, value) {
    try {
      const fn = new Function("value", "with(this){" + expr + " = value}");
      fn.call(scope, value);
    } catch (e) { /* ignore */ }
  }

  function parseBindings(el) {
    const bindings = {};
    for (const attr of Array.from(el.attributes)) {
      if (attr.name.startsWith("x-")) {
        bindings[attr.name.slice(2)] = attr.value;
      }
    }
    return bindings;
  }

  function walk(el, scope) {
    if (el.nodeType === Node.ELEMENT_NODE) {
      const bindings = parseBindings(el);
      let childScope = scope;

      if (bindings["data"]) {
        const dataExpr = bindings["data"];
        const data = evaluate(dataExpr, scope) || {};
        childScope = Object.create(scope);
        Object.assign(childScope, data);
        if (typeof childScope.init === "function") {
          childScope.init();
        }
      }

      if (bindings["show"]) {
        const show = !!evaluate(bindings["show"], childScope);
        el.style.display = show ? "" : "none";
        if (!show) el.setAttribute("x-cloak", "");
        else el.removeAttribute("x-cloak");
      }

      if (bindings["text"] !== undefined) {
        const val = evaluate(bindings["text"], childScope);
        el.textContent = val === undefined || val === null ? "" : String(val);
      }

      if (bindings["html"] !== undefined) {
        const val = evaluate(bindings["html"], childScope);
        el.innerHTML = val === undefined || val === null ? "" : String(val);
      }

      if (bindings["model"] !== undefined) {
        const val = evaluate(bindings["model"], childScope);
        if (el.type === "checkbox") {
          el.checked = !!val;
        } else if (el.type === "range") {
          el.value = val === undefined ? el.value : val;
        } else {
          el.value = val === undefined || val === null ? "" : String(val);
        }
        el.addEventListener("input", () => {
          let v = el.value;
          if (el.type === "range") v = parseFloat(v);
          if (el.type === "checkbox") v = el.checked;
          evaluateAssignment(bindings["model"], childScope, v);
        });
      }

      if (bindings["for"]) {
        // x-for="item in items"
        const m = bindings["for"].match(/^(\w+)(?:,\s*(\w+))?\s+in\s+(.+)$/);
        if (m) {
          const [, itemName, indexName, listExpr] = m;
          const list = evaluate(listExpr, childScope) || [];
          const template = el.content ? el.content : el;
          const parent = el.parentNode;
          Array.from(parent.children).forEach((c) => {
            if (c.hasAttribute && c.hasAttribute("data-x-for")) c.remove();
          });
          list.forEach((item, idx) => {
            const clone = document.importNode(template, true);
            const cs2 = Object.create(childScope);
            cs2[itemName] = item;
            if (indexName) cs2[indexName] = idx;
            walk(clone, cs2);
            clone.setAttribute("data-x-for", "1");
            parent.insertBefore(clone, el.nextSibling);
          });
          return;
        }
      }

      if (bindings["bind"]) {
        // x-bind:href="expr"
        const parts = bindings["bind"].split(":");
        if (parts.length === 2) {
          const attr = parts[0];
          const val = evaluate(parts[1], childScope);
          if (val !== undefined && val !== null) el.setAttribute(attr, String(val));
        }
      }

      if (bindings["on"]) {
        // x-on:click="expr"
        const parts = bindings["on"].split(":");
        if (parts.length === 2) {
          const event = parts[0];
          const expr = parts[1];
          el.addEventListener(event, (ev) => {
            evaluate(expr, Object.assign(Object.create(childScope), { $event: ev }));
          });
        }
      }

      if (bindings["click.away"]) {
        document.addEventListener("click", (ev) => {
          if (!el.contains(ev.target)) {
            evaluate(bindings["click.away"], childScope);
          }
        });
      }

      if (bindings["init"]) {
        evaluate(bindings["init"], childScope);
      }

      for (const child of el.children) {
        walk(child, childScope);
      }
    }
  }

  function start() {
    document.querySelectorAll("[x-data]").forEach((el) => {
      walk(el, {});
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }
})();
